result.text:
.toolbar { display:flex; gap:12px; align-items:center; padding:12px 16px; flex-wrap:wrap; }
.grid { border-collapse:collapse; margin:0 16px; }
.grid th, .grid td { border-bottom:1px solid var(--line); padding:6px 10px; text-align:left; }
.grid tr.is-filtered { display:none; }
.grid .rowlink { display:inline-block; }
.grid .rowlink .track { margin-left:8px; font-size:12px; }
.box { display:inline-block; width:16px; height:16px; border:1px solid var(--ink); }
.box[aria-checked=true] { background:var(--accent); }
.listbox { position:absolute; background:#fff; border:1px solid var(--line); margin:0; padding:4px; list-style:none; }
.listbox[hidden] { display:none; }
.toast-host { position:fixed; right:16px; bottom:16px; }
.toast-host:empty { display:none; }
.legend { height:20px; width:260px; }
.spark { width:60px; height:16px; }
.pager button[aria-current] { font-weight:700; }
dialog.confirm { border:1px solid var(--line); padding:16px; }
#row-menu { border:1px solid var(--line); padding:4px; }
#row-menu [role=menuitem] { display:block; padding:4px 8px; }
iframe.preview { width:320px; height:140px; border:1px solid var(--line); margin:12px 16px; }
#q:placeholder-shown ~ .clear { display:none; }
.help { display:none; position:fixed; left:16px; bottom:16px; width:420px; padding:8px 12px; border:1px solid var(--line); background:#fff; }
.help:target { display:block; }
.print-only, .hc-label { display:none; }
@media (prefers-contrast: more) { .hc-label { display:inline; } }
@media print {
  .site-header nav, .toolbar, .pager, .toast-host { display:none; }
  .print-only { display:block; }
}
.grid .fresh { margin-left:6px; font-size:11px; color:var(--accent); animation: lapse 0s linear 15s forwards; }
.grid .more { visibility:hidden; }
.grid tr:hover .more, .grid tr:focus-within .more { visibility:visible; }
.tip { display:none; position:fixed; left:460px; bottom:16px; width:380px; padding:8px 12px; border:1px solid var(--line); background:#fff; }

:host summary {
  display: list-item;
  counter-increment: list-item 0;
  list-style: disclosure-closed inside;
}
:host([open]) summary {
  list-style-type: disclosure-open;
}

:root { --ink:#1c2430; --line:#c9d1dc; --accent:#0b5cad; }
* { box-sizing: border-box; }
body { margin:0; font:15px/1.45 system-ui, sans-serif; color:var(--ink); }
.sr-only { position:absolute; width:1px; height:1px; overflow:hidden; clip-path:inset(50%); white-space:nowrap; }
.skip-link { position:absolute; left:-999px; }
.skip-link:focus { left:8px; top:8px; }
.site-header { display:flex; gap:16px; align-items:center; padding:8px 16px; border-bottom:1px solid var(--line); }
.logo { height:24px; width:96px; }
.only-dark { display:none; }
@media (prefers-color-scheme: dark) {
  .only-dark { display:inline; }
  .only-light { display:none; }
}
.nav-toggle { display:none; }
#primary-nav ul { display:flex; gap:12px; list-style:none; margin:0; padding:0; }
@media (max-width: 720px) {
  .nav-toggle { display:inline-flex; }
  #primary-nav { display:none; }
  #primary-nav[data-open] { display:block; }
  .col-wide { display:none; }
}
.Banner { padding:8px 16px; background:#fff4d6; }
.Banner-Dismissed { display:none; }
.crumbs ol { display:contents; list-style:none; }
.crumbs li { display:inline; }
.crumbs li + li::before { content:"/ " / ""; }
[data-busy] > * { visibility:hidden; }
[data-busy] > .spinner { visibility:visible; }
h1.page-title::before { content:"\25B8  "; }
.req::after { content:" *" / " (required)"; }
.field-error { display:none; color:#a40000; }
.is-invalid ~ .field-error { display:block; }
.caps { text-transform:uppercase; }
.tabpanel[hidden] { display:none; }
.tree [role=group] { padding-left:16px; }
.tree [aria-expanded=false] + [role=group] { display:none; }
.cv-hidden { content-visibility:hidden; }
@keyframes lapse { to { visibility:hidden; } }
@keyframes arrive { to { visibility:visible; } }
.toast { animation: lapse 0s linear 12s forwards; }

