.form-grid { display:grid; grid-template-columns: 180px 1fr; gap:8px 12px; padding:16px; max-width:720px; }
.hint { font-size:12px; color:#556; }
.native-hint { display:none; }
.idle-hint { visibility:hidden; animation: arrive 0s linear 25s forwards; }
#f-consignee:invalid ~ .native-hint { display:block; }
.panel-note[hidden] { display:none; }
.unsaved { position:fixed; left:16px; bottom:16px; width:420px; padding:8px 12px; border:1px solid #c9d1dc; background:#fff; }
.timeline { list-style:none; padding:0 16px; }
.timeline li[data-kind=system] { display:none; }
.show-system .timeline li[data-kind=system] { display:list-item; }

